<?php
namespace app\controller;use app\BaseController;use app\service\QuotaLotService;use app\service\GatewayCache;use think\facade\Db;use think\facade\Session;use think\facade\View;
class User extends BaseController{
 private function quotaSig(array $u):string{$secret=trim((string)@file_get_contents((string)(getenv('LUMEN_INTEGRITY_KEY_FILE')?:'/www/server/lumenapi/integrity.key')));return hash_hmac('sha256',$u['id'].'|'.($u['quota_total']===null?'NULL':$u['quota_total']).'|'.$u['quota_used'],$secret);}
 private function quotaIntegrityOk(array $u):bool{return !empty($u['quota_integrity_hash'])&&hash_equals((string)$u['quota_integrity_hash'],$this->quotaSig($u));}
 private function lockIntegrity(int $id,string $reason):void{Db::name('users')->where('id',$id)->update(['integrity_locked'=>1,'integrity_reason'=>mb_substr($reason,0,500),'integrity_locked_at'=>date('Y-m-d H:i:s'),'status'=>0,'key_status'=>0,'updated_at'=>date('Y-m-d H:i:s')]);}

 private function uid(){return (int)Session::get('lumen_user_id');} private function guard(){return $this->uid()?null:redirect('/user/login');}
 private function audit($action,$id,$detail=''){Db::name('audit_logs')->insert(['admin_id'=>null,'action'=>$action,'target_type'=>'user','target_id'=>$id?:null,'detail'=>$detail,'ip'=>request()->ip(),'created_at'=>date('Y-m-d H:i:s')]);}
 public function home(){ $apis=Db::name('endpoints')->where('status',1)->where('access_level','public')->field('name,slug,method,cost_per_call,description')->order('id','asc')->select()->toArray();View::assign('apis',$apis);return View::fetch(root_path().'view/user/home.html');}
 private function registrationEnabled():bool{return (string)(Db::name('settings')->where('key','user.registration_enabled')->value('value')??'1')==='1';}
 public function register(){if(!$this->registrationEnabled())return response('当前暂停新用户注册',403);if($this->uid())return redirect('/user');View::assign('error','');return View::fetch(root_path().'view/user/register.html');}
 public function create(){if(!$this->registrationEnabled())return response('当前暂停新用户注册',403);if($this->uid())return redirect('/user');$u=trim((string)input('post.username',''));$email=trim((string)input('post.email',''));$p=(string)input('post.password','');$p2=(string)input('post.password_confirm','');if(!preg_match('/^[A-Za-z0-9_]{3,32}$/',$u))return $this->regErr('用户名需 3-32 位，只能使用字母、数字和下划线。');if(strlen($p)<8)return $this->regErr('密码至少 8 位。');if($p!==$p2)return $this->regErr('两次密码不一致。');if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))return $this->regErr('邮箱格式不正确。');if(Db::name('users')->where('username',$u)->find())return $this->regErr('用户名已存在。');if($email!==''&&Db::name('users')->where('email',$email)->find())return $this->regErr('邮箱已存在。');$now=date('Y-m-d H:i:s');$initialSetting=Db::name('settings')->where('key','user.initial_quota')->value('value');$initialQuota=max(0,(int)($initialSetting ?? 0));$secret=trim((string)@file_get_contents((string)(getenv('LUMEN_INTEGRITY_KEY_FILE')?:'/www/server/lumenapi/integrity.key')));if($secret==='')return response('注册暂不可用：完整性签名密钥未配置',503);$id=Db::transaction(function()use($u,$email,$p,$now,$initialQuota){$id=Db::name('users')->insertGetId(['username'=>$u,'email'=>$email?:null,'password_hash'=>password_hash($p,PASSWORD_DEFAULT),'status'=>1,'quota_total'=>$initialQuota,'quota_used'=>0,'trusted_quota_total'=>$initialQuota,'trusted_quota_used'=>0,'created_at'=>$now,'updated_at'=>$now]);$sig=$this->quotaSig(['id'=>$id,'quota_total'=>$initialQuota,'quota_used'=>0]);Db::name('users')->where('id',$id)->update(['quota_integrity_hash'=>$sig]);QuotaLotService::createFreeLot($id,'register_bonus',$id,$initialQuota);$this->audit('user.register',$id,'username='.$u);return $id;});Session::clear();Session::regenerate(true);Session::set('lumen_user_id',$id);Session::set('lumen_user_username',$u);return redirect('/user');}
 private function regErr($e){View::assign('error',$e);return View::fetch(root_path().'view/user/register.html');}
 public function login(){if($this->uid())return redirect('/user');View::assign('error','');return View::fetch(root_path().'view/user/login.html');}
 public function authenticate(){$u=trim((string)input('post.username',''));$p=(string)input('post.password','');$since=date('Y-m-d H:i:s',time()-600);if(Db::name('audit_logs')->where('action','user.login_failed')->where('ip',request()->ip())->where('created_at','>=',$since)->count()>=8){View::assign('error','登录失败次数过多，请稍后再试。');return View::fetch(root_path().'view/user/login.html');}$x=Db::name('users')->where('username',$u)->find();if(!$x||!password_verify($p,$x['password_hash'])){$this->audit('user.login_failed',0,'username='.mb_substr($u,0,32));View::assign('error','用户名或密码错误。');return View::fetch(root_path().'view/user/login.html');}if(!$x['status']){View::assign('error','账号已被封禁：'.($x['ban_reason']?:'请联系管理员'));return View::fetch(root_path().'view/user/login.html');}Session::clear();Session::regenerate(true);Session::set('lumen_user_id',(int)$x['id']);Session::set('lumen_user_username',$x['username']);Db::name('users')->where('id',$x['id'])->update(['last_login_at'=>date('Y-m-d H:i:s'),'last_login_ip'=>request()->ip(),'updated_at'=>date('Y-m-d H:i:s')]);$this->audit('user.login',$x['id'],'');return redirect('/user');}
 public function status(){if(!$this->uid())return json(['authenticated'=>false],401);$u=Db::name('users')->where('id',$this->uid())->find();if(!$u||!$this->quotaIntegrityOk($u)){if($u)$this->lockIntegrity((int)$u['id'],'额度完整性校验失败：账户额度与可信签名不一致');Session::clear();return json(['authenticated'=>false,'locked'=>true],401);}if(!$u['status']||!empty($u['integrity_locked'])){Session::clear();return json(['authenticated'=>false,'locked'=>!empty($u['integrity_locked'])],401);}return json(['authenticated'=>true,'locked'=>false]);}
 public function dashboard(){if($r=$this->guard())return$r;$u=Db::name('users')->where('id',$this->uid())->find();if($u&&!$this->quotaIntegrityOk($u)){$this->lockIntegrity((int)$u['id'],'额度完整性校验失败：账户额度与可信签名不一致');Session::clear();return redirect('/user/login');}if(!$u||!$u['status']||!empty($u['integrity_locked'])){Session::clear();return redirect('/user/login');}$keys=Db::name('keys')->where('user_id',$u['id'])->order('id','desc')->select()->toArray();foreach($keys as &$k){$k['quota_total']=$u['quota_total'];$k['quota_used']=(int)$u['quota_used'];}unset($k);$new=Session::pull('lumen_user_new_key','');$apis=Db::name('endpoints')->where('status',1)->where('access_level','public')->field('id,name,slug,method,auth_mode,cost_per_call,description')->order('id','asc')->select()->toArray();foreach($apis as &$api){$api['success_count']=(int)Db::name('billing_logs')->where('user_id',$u['id'])->where('endpoint_id',$api['id'])->count();$api['spent']=(int)Db::name('billing_logs')->where('user_id',$u['id'])->where('endpoint_id',$api['id'])->sum('amount');}unset($api);$ledger=Db::name('quota_ledger')->where('user_id',$u['id'])->order('id','desc')->limit(30)->select()->toArray();View::assign(['user'=>$u,'keys'=>$keys,'newKey'=>$new,'apis'=>$apis,'ledger'=>$ledger]);return View::fetch(root_path().'view/user/dashboard.html');}
 public function resetKey(){if($r=$this->guard())return$r;$uid=$this->uid();$u=Db::name('users')->where('id',$uid)->where('status',1)->find();if(!$u)return redirect('/user/login');$plain='lmn_'.bin2hex(random_bytes(24));$now=date('Y-m-d H:i:s');GatewayCache::forgetUser($uid);Db::transaction(function()use($uid,$u,$plain,$now){Db::name('keys')->where('user_id',$uid)->where('status',1)->update(['status'=>0,'ban_source'=>'system','ban_reason'=>'用户主动重置 Key，旧 Key 已失效','banned_at'=>$now,'updated_at'=>$now]);Db::name('keys')->insert(['user_id'=>$uid,'name'=>$u['username'].' Default','key_prefix'=>substr($plain,0,12),'key_hash'=>hash('sha256',$plain),'status'=>((int)($u['penalty_debt']??0)>0?0:1),'ban_source'=>((int)($u['penalty_debt']??0)>0?'penalty':null),'ban_reason'=>((int)($u['penalty_debt']??0)>0?'账户存在未结清处罚':null),'banned_at'=>null,'quota_total'=>$u['quota_total'],'quota_used'=>(int)$u['quota_used'],'created_at'=>$now,'updated_at'=>$now]);});Session::set('lumen_user_new_key',$plain);$this->audit('user.api_key.reset',$uid,'old active keys disabled');return redirect('/user');}

 public function createKey(){if($r=$this->guard())return$r;$uid=$this->uid();$u=Db::name('users')->where('id',$uid)->where('status',1)->find();if(!$u)return redirect('/user/login');$name=trim((string)input('post.name',''));if($name===''||mb_strlen($name)>100)return response('Key 名称需 1-100 字符',422);if(Db::name('keys')->where('user_id',$uid)->count()>=20)return response('每个账户最多创建 20 个 Key',422);$plain='lmn_'.bin2hex(random_bytes(24));$now=date('Y-m-d H:i:s');$paused=((int)($u['penalty_debt']??0)>0||(int)$u['key_status']!==1);$id=Db::name('keys')->insertGetId(['user_id'=>$uid,'name'=>$name,'key_prefix'=>substr($plain,0,12),'key_hash'=>hash('sha256',$plain),'status'=>$paused?0:1,'ban_source'=>$paused?'system':null,'ban_reason'=>$paused?'账户级 Key 当前不可用':null,'quota_total'=>$u['quota_total'],'quota_used'=>(int)$u['quota_used'],'created_at'=>$now,'updated_at'=>$now]);Session::set('lumen_user_new_key',$plain);$this->audit('user.api_key.create',$uid,'key_id='.$id.'; name='.mb_substr($name,0,100));return redirect('/user');}
 public function toggleKey($id){if($r=$this->guard())return$r;$uid=$this->uid();$k=Db::name('keys')->where('id',(int)$id)->where('user_id',$uid)->find();if(!$k)return response('Not Found',404);$u=Db::name('users')->where('id',$uid)->find();$now=date('Y-m-d H:i:s');if($k['status']){Db::name('keys')->where('id',$k['id'])->update(['status'=>0,'ban_source'=>'user','ban_reason'=>'用户主动暂停','banned_at'=>$now,'updated_at'=>$now]);$action='pause';}else{if(!$u||!$u['status']||!$u['key_status']||!empty($u['integrity_locked'])||(int)($u['penalty_debt']??0)>0)return response('账户当前不允许启用 Key',403);if(($k['ban_source']??'')==='system'&&str_contains((string)$k['ban_reason'],'重置'))return response('该 Key 已吊销，不能重新启用',403);Db::name('keys')->where('id',$k['id'])->update(['status'=>1,'ban_source'=>null,'ban_reason'=>null,'banned_at'=>null,'updated_at'=>$now]);$action='resume';}GatewayCache::forgetKeyHash((string)$k['key_hash']);$this->audit('user.api_key.'.$action,$uid,'key_id='.$k['id']);return redirect('/user');}
 public function revokeKey($id){if($r=$this->guard())return$r;$uid=$this->uid();$k=Db::name('keys')->where('id',(int)$id)->where('user_id',$uid)->find();if(!$k)return response('Not Found',404);$now=date('Y-m-d H:i:s');Db::name('keys')->where('id',$k['id'])->update(['status'=>0,'ban_source'=>'system','ban_reason'=>'用户永久吊销','banned_at'=>$now,'updated_at'=>$now]);GatewayCache::forgetKeyHash((string)$k['key_hash']);$this->audit('user.api_key.revoke',$uid,'key_id='.$k['id']);return redirect('/user');}

 public function apiDoc($slug){if($r=$this->guard())return$r;$u=Db::name('users')->where('id',$this->uid())->find();if($u&&!$this->quotaIntegrityOk($u)){$this->lockIntegrity((int)$u['id'],'额度完整性校验失败：账户额度与可信签名不一致');Session::clear();return redirect('/user/login');}if(!$u||!$u['status']||!empty($u['integrity_locked'])){Session::clear();return redirect('/user/login');}$api=Db::name('endpoints')->where('slug',$slug)->where('status',1)->where('access_level','public')->find();if(!$api)return response('API Not Found',404);$params=Db::name('endpoint_params')->where('endpoint_id',$api['id'])->order('sort_order,id')->select()->toArray();View::assign(['user'=>$u,'api'=>$api,'params'=>$params]);return View::fetch(root_path().'view/user/api_doc.html');}
 public function logout(){if($this->uid())$this->audit('user.logout',$this->uid(),'');Session::clear();return redirect('/user/login');}
}
